def changed_paths(before, after):
    """Return sorted dot-separated paths for additions, removals, or unequal leaves.

    Recurses only where both values are dicts. Lists are compared atomically.
    If an entire dict key is added or removed, only that parent path is returned.
    """
    paths = set()
    _diff(before, after, "", paths)
    return sorted(paths)


def _diff(before, after, prefix, paths):
    all_keys = set(before.keys()) | set(after.keys())
    for key in all_keys:
        path = prefix + "." + key if prefix else key
        if key not in before:
            paths.add(path)
        elif key not in after:
            paths.add(path)
        else:
            b_val = before[key]
            a_val = after[key]
            if isinstance(b_val, dict) and isinstance(a_val, dict):
                _diff(b_val, a_val, path, paths)
            elif b_val != a_val:
                paths.add(path)
