import heapq


def order(deps):
    """Return a topological ordering of all nodes in deps, always choosing
    the alphabetically smallest currently ready node. Raise ValueError on a cycle."""
    # Collect all nodes (keys and all prerequisite values)
    nodes = set(deps.keys())
    for prereqs in deps.values():
        for p in prereqs:
            nodes.add(p)

    # Build reverse adjacency and in-degrees
    dependents = {n: [] for n in nodes}
    in_degree = {n: 0 for n in nodes}

    for node, prereqs in deps.items():
        for p in set(prereqs):  # guard against duplicate listings
            dependents[p].append(node)
            in_degree[node] += 1

    # Min-heap seeded with all initially ready nodes (no prerequisites)
    heap = [n for n in nodes if in_degree[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dependent in dependents[node]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected in dependency graph")

    return result
```

