def redact(value, sensitive):
    """Recursively copy a JSON-like structure, redacting sensitive keys.

    Args:
        value: The input data (dict, list, or scalar).
        sensitive: A list of strings whose case-insensitive match against
                   dictionary keys triggers redaction.

    Returns:
        A new structure of the same shape with matching keys replaced by
        "[REDACTED]". The original input is not mutated.
    """
    sensitive_lower = frozenset(s.lower() for s in sensitive)

    def _walk(node):
        if isinstance(node, dict):
            return {
                key: ("[REDACTED]" if key.lower() in sensitive_lower else _walk(val))
                for key, val in node.items()
            }
        if isinstance(node, list):
            return [_walk(item) for item in node]
        return node

    return _walk(value)
```

